  { id:"snail", name:"snail", ic:"🐚", sci:"Achatina fulica", group:"Mollusca · Gastropoda", feat:{ joint:false, legs:0, antenna:false, shell:true, radial:false, segments:false, claws:false, many:false, onepair:false, twopair:false } },
  { id:"earthworm", name:"earthworm", ic:"🪱", sci:"Pheretima posthuma", group:"Annelida · Clitellata", feat:{ joint:false, legs:0, antenna:false, shell:false, radial:false, segments:true, claws:false, many:false, onepair:false, twopair:false } },
  { id:"starfish", name:"sea star", ic:"⭐", sci:"Aquilonastra batheri", group:"Echinodermata · Asteroidea", feat:{ joint:false, legs:0, antenna:false, shell:false, radial:true, segments:false, claws:false, many:false, onepair:false, twopair:false } }
