  root.innerHTML = `<div class="simgrid wide"><section class="card"><div id="classSvg" class="simsvg nozoom"></div><div class="p2b-ctl"><div><b class="small">Mode</b>${segBtns("cls-mode", [["use","🔑 Use key"],["build","🛠️ Build key"],["rank","🏷️ Names"]], st.mode)}</div><div id="classControls"></div></div></section><section class="card"><h3 style="margin:0">📋 Key panel</h3><div id="classPanel"></div></section></div>`;
  const resetKey = () => { st.node = 0; st.result = ""; };
  const draw = () => { root.querySelector("#classSvg").innerHTML = classifySvg(st); root.querySelector("#classControls").innerHTML = classifyControls(st); root.querySelector("#classPanel").innerHTML = classifyPanel(st); wire(); };
  const wire = () => {
    root.querySelectorAll("[data-cls-mode]").forEach(b => { b.setAttribute("aria-checked", b.dataset.clsMode===st.mode?"true":"false"); b.onclick=()=>{SFX.tap();st.mode=b.dataset.clsMode;draw();}; });
    root.querySelectorAll("[data-cls-org]").forEach(b=>b.onclick=()=>{SFX.tap();st.org=b.dataset.clsOrg;resetKey();draw();});
    root.querySelectorAll("[data-cls-ans]").forEach(b=>b.onclick=()=>{SFX.tap(); const n=CLS_TREE[st.node], next=b.dataset.clsAns==="yes"?n.yes:n.no; if(typeof next==="number") st.node=next; else st.result=next; draw();});
    root.querySelectorAll("[data-cls-q]").forEach(b=>b.onclick=()=>{SFX.tap(); const id=b.dataset.clsQ, i=st.build.indexOf(id); if(i>=0) st.build.splice(i,1); else st.build.push(id); draw();});
    root.querySelector("#clsClear") && (root.querySelector("#clsClear").onclick=()=>{SFX.tap();st.build=[];draw();});
  };
