function clsOrg(id){return CLS_ORGS.find(o=>o.id===id)||CLS_ORGS[0];}
function classifyProbe(st){ const groups=classifyGroups(st), good=groups.length===CLS_ORGS.length&&groups.every(g=>g.items.length===1), max=groups.reduce((m,g)=>Math.max(m,g.items.length),0); return { mode:st.mode, selected:st.org, selectedName:clsOrg(st.org).name, keyResult:st.result?clsOrg(st.result).name:"", keyCorrect:st.result===st.org, node:st.node, buildCount:st.build.length, buildSolved:good, buildMaxGroup:max, groups:groups.length, domainOrder:"Domain>Kingdom>Phylum>Class>Order>Family>Genus>Species" }; }
function classifyGroups(st){ const qs=st.build.map(id=>CLS_QS.find(q=>q.id===id)).filter(Boolean); const m={}; CLS_ORGS.forEach(o=>{ const code=qs.map(q=>q.yes(o)?"Y":"N").join("")||"unsorted"; (m[code]=m[code]||[]).push(o); }); return Object.keys(m).sort().map(k=>({code:k,items:m[k]})); }
function classifyControls(st){ if(st.mode==="rank") return `<p class="p2b-note">Use observable features for keys. Use hierarchy for naming relationships.</p>`; return `<div class="p2b-orgrow">${CLS_ORGS.map(o=>`<button data-cls-org="${o.id}" aria-pressed="${o.id===st.org}">${o.ic} ${o.name}</button>`).join("")}</div>`; }
function classifyPanel(st){ if(st.mode==="use"){ const n=CLS_TREE[st.node], org=clsOrg(st.org); return `<div class="p2b-keybox"><div class="p2b-keyq"><b>Specimen: ${org.ic} ${esc(org.name)}</b><span>${esc(org.group)} · <i>${esc(org.sci)}</i></span></div>${st.result?`<p class="p2b-note">Result: <b>${esc(clsOrg(st.result).name)}</b> ${st.result===st.org?"✅ correct":"❌ try again"}</p><button class="btn" data-cls-org="${st.org}">↺ Start this key again</button>`:`<div class="p2b-keyq"><b>${esc(n.q)}</b><div class="row simbtns"><button class="btn" data-cls-ans="yes">Yes</button><button class="btn plain" data-cls-ans="no">No</button></div></div>`}</div>`; }
  if(st.mode==="build"){ const groups=classifyGroups(st), good=groups.length===CLS_ORGS.length&&groups.every(g=>g.items.length===1); return `<p class="p2b-note"><b>Build rule:</b> choose questions so every endpoint has exactly 1 organism. Current: <b>${groups.filter(g=>g.items.length===1).length}/${CLS_ORGS.length}</b> single endpoints ${good?"🏆":""}</p><div class="p2b-qrow">${CLS_QS.map(q=>`<button data-cls-q="${q.id}" aria-pressed="${st.build.includes(q.id)}">${st.build.includes(q.id)?"✓":"+"} ${esc(q.q)}</button>`).join("")}<button id="clsClear">Clear</button></div><div class="p2b-split">${groups.map(g=>`<span class="${g.items.length===1?"ok":""}"><b>${esc(g.code)}</b>${g.items.map(o=>`${o.ic} ${o.name}`).join(" · ")}</span>`).join("")}</div>`; }
  return `<div class="p2b-tax">${["Domain","Kingdom","Phylum","Class","Order","Family","Genus","Species"].map((r,i)=>`<span><b>${r}</b>${"●".repeat(i+1)}${"○".repeat(7-i)}</span>`).join("")}</div><div class="p2b-namecards"><div>Human<br><i>Homo sapiens</i><br><small>Animalia · Chordata · Mammalia</small></div><div>Chinese white dolphin<br><i>Sousa chinensis</i><br><small>Animalia · Chordata · Mammalia</small></div><div>Romer's tree frog<br><i>Liuixalus romeri</i><br><small>Animalia · Chordata · Amphibia</small></div><div>Hong Kong orchid tree<br><i>Bauhinia × blakeana</i><br><small>Plantae · flowering plant</small></div></div><p class="p2b-note">Three domains: <b>Bacteria, Archaea, Eukarya</b>. Five kingdoms: <b>Prokaryotae, Protoctista, Fungi, Plantae, Animalia</b>.</p>`; }
function classifySvg(st){ const org=clsOrg(st.org); return `<svg viewBox="0 0 320 620" role="img" aria-label="Classification specimens and dichotomous key features"><rect width="320" height="620" rx="16" fill="#FFF9ED"/><text x="160" y="24" text-anchor="middle" font-size="12" font-weight="900" fill="${CO}">Observable features, not guesses</text><g transform="translate(10 38)">${CLS_ORGS.map((o,i)=>{const px=(i%2)*150,py=Math.floor(i/2)*124;return `<g transform="translate(${px} ${py})"><rect width="140" height="112" rx="14" fill="${o.id===st.org?"#EAF6FF":"#fff"}" stroke="${o.id===st.org?"#3E8FDF":CO}" stroke-width="2.4"/>${classifyCreatureSvg(o.id,o.id==="centipede"||o.id==="millipede"?48:70,50)}<text x="70" y="92" text-anchor="middle" font-size="10" font-weight="900" fill="${CO}">${esc(o.name)}</text><text x="70" y="106" text-anchor="middle" font-size="10" font-weight="900" fill="#7A6A66">${o.feat.legs?o.feat.legs+" legs":o.feat.shell?"shell":o.feat.radial?"5 arms":"segments"}</text></g>`;}).join("")}</g><g font-size="11" font-weight="900" fill="${CO}"><text x="16" y="546">Selected: ${org.ic} ${esc(org.name)}</text><text x="16" y="564">${esc(org.group)}</text><text x="16" y="583">Scientific name:</text><text x="116" y="583" font-style="italic">${esc(org.sci)}</text></g></svg>`; }
