const EVO_CHAIN = ["Variation from mutation", "Overproduction", "Struggle for existence", "Better adapted survive", "Survivors reproduce", "Alleles passed on", "Allele frequency changes"];
function evolveSim(root){ const st={bark:"clean",strength:60,dark:30,start:30,gen:0,run:false,hist:[30],scenario:"moth"}; root.innerHTML=`<div class="simgrid wide"><section class="card"><div id="evoSvg" class="simsvg nozoom"></div><div class="p2b-legend"><span>👁 More visible = more likely eaten</span><span>🛡 Camouflaged = survives more</span></div><div class="p2b-ctl"><div><b class="small">Bark</b>${segBtns("evo-bark", [["clean","🌿 Clean pale"],["sooty","🏭 Sooty dark"]], st.bark)}</div><label><span>🦅 Predation strength <b id="evoStrLab">60%</b></span><input id="evoStr" type="range" min="10" max="100" step="5" value="60"></label><label><span>⚫ Starting dark form <b id="evoStartLab">30%</b></span><input id="evoStart" type="range" min="0" max="100" step="5" value="30"></label><div class="row simbtns"><button class="btn" id="evoStep">Step generation</button><button class="btn yellow" id="evoRun">▶ Play</button><button class="btn plain" id="evoReset">↺ Reset</button></div></div></section><section class="card"><h3 style="margin:0">📈 Allele / form graph</h3><div id="evoGraph" class="simsvg nozoom"></div><div id="evoRead" class="p2b-read"></div><h3 style="margin:0">🧠 Selection chain</h3><div id="evoChain" class="p2b-chain"></div></section></div><section class="card"><h3 style="margin:0">🪨 Evidence + second scenario</h3><div class="simgrid"><div id="evoFossil" class="simsvg nozoom"></div><div id="evoBact" class="simsvg nozoom"></div></div></section>`;
  const reset=()=>{st.dark=st.start;st.gen=0;st.hist=[st.dark];}; const step=()=>{const d=evolveNext(st);st.dark=d;st.gen++;st.hist.push(+d.toFixed(1));st.hist=st.hist.slice(-31);}; const draw=()=>{root.querySelector("#evoSvg").innerHTML=evolveSceneSvg(st);root.querySelector("#evoGraph").innerHTML=evolveGraphSvg(st);root.querySelector("#evoRead").innerHTML=evolveReadHtml(st);root.querySelector("#evoChain").innerHTML=EVO_CHAIN.map((x,i)=>`<span class="${i===Math.min(6,st.gen%7)?"on":""}">${i+1}. ${x}</span>`).join("");root.querySelector("#evoFossil").innerHTML=evolveFossilSvg();root.querySelector("#evoBact").innerHTML=evolveBacteriaSvg(st);wire();};
  const wire=()=>{root.querySelectorAll("[data-evo-bark]").forEach(b=>{b.setAttribute("aria-checked",b.dataset.evoBark===st.bark?"true":"false");b.onclick=()=>{SFX.tap();st.bark=b.dataset.evoBark;draw();};});root.querySelector("#evoStr").oninput=e=>{st.strength=Number(e.target.value);root.querySelector("#evoStrLab").textContent=st.strength+"%";draw();};root.querySelector("#evoStart").oninput=e=>{st.start=Number(e.target.value);root.querySelector("#evoStartLab").textContent=st.start+"%"; if(st.gen===0){st.dark=st.start;st.hist=[st.dark];} draw();};root.querySelector("#evoStep").onclick=()=>{SFX.tap();step();draw();};root.querySelector("#evoRun").onclick=()=>{SFX.tap();st.run=!st.run;draw();};root.querySelector("#evoReset").onclick=()=>{SFX.tap();st.run=false;reset();draw();};};
  simProbe(()=>evolveProbe(st)); simLoop(root,dt=>{if(st.run){st.acc=(st.acc||0)+dt*1.6;if(st.acc>=1){st.acc=0;step();draw();}}}); draw(); }
function evolveNext(st){ const p=st.dark/100, s=st.strength/100, vd=st.bark==="clean"?.82:.22, vl=st.bark==="clean"?.22:.82, sd=1-s*vd*.78, sl=1-s*vl*.78, nd=p*sd, nl=(1-p)*sl, mut=.002; return clamp((nd/(nd+nl))*(1-mut)+mut*50,0,100); }
function evolveProbe(st){ const next=evolveNext(st), change=next-st.dark; return { bark:st.bark, strength:st.strength, darkPct:+st.dark.toFixed(1), lightPct:+(100-st.dark).toFixed(1), generation:st.gen, running:st.run, nextDark:+next.toFixed(1), change:+change.toFixed(1), darkIncreasing:change>0, clean:st.bark==="clean", sooty:st.bark==="sooty", histLen:st.hist.length }; }
function evolveReadHtml(st){ const p=evolveProbe(st); return `<span>Generation<b>${p.generation}</b></span><span>Dark form<b>${p.darkPct}%</b></span><span>Light form<b>${p.lightPct}%</b></span><span>Next change<b>${p.change>0?"▲":"▼"} ${Math.abs(p.change).toFixed(1)}%</b></span>`; }
function evolveSceneSvg(st){ const darkN=Math.round(st.dark/10), moths=Array.from({length:10},(_,i)=>i<darkN), ink=st.bark==="clean"?CO:"#fff"; return `<svg viewBox="0 0 320 450" role="img" aria-label="Peppered moths on ${st.bark} bark"><defs><pattern id="barkPat" width="64" height="64" patternUnits="userSpaceOnUse"><rect width="64" height="64" fill="${st.bark==="clean"?"#B9C7A3":"#4A4542"}"/><path d="M7 0 q18 28 0 64 M31 0 q-14 32 0 64 M54 0 q20 27 0 64" stroke="${st.bark==="clean"?"#7E8F6D":"#2E2B2A"}" stroke-width="7" fill="none" opacity=".7"/><path d="M0 18 q30 -10 64 4 M0 45 q28 8 64 -2" stroke="${st.bark==="clean"?"#DCE8C6":"#68605A"}" stroke-width="2.5" fill="none" opacity=".75"/></pattern></defs><rect width="320" height="450" rx="16" fill="url(#barkPat)"/><text x="160" y="24" text-anchor="middle" font-size="11" font-weight="900" fill="${ink}">${st.bark==="clean"?"Clean pale bark":"Sooty dark bark"}</text><g transform="translate(222 34) scale(.72)"><path d="M36 20 q28 -30 72 0 q-26 -2 -44 20 q20 8 36 32 q-34 -8 -58 -34 q-10 22 -36 34 q8 -26 30 -52Z" fill="#6B4A45" stroke="${CO}" stroke-width="3"/><circle cx="88" cy="16" r="8" fill="#111"/></g><text x="263" y="110" text-anchor="middle" font-size="10" font-weight="900" fill="${ink}">bird predator</text>${moths.map((dark,i)=>{const x=74+(i%2)*132,y=82+Math.floor(i/2)*66;return evolveMothSvg(x,y,dark,st.bark,i,.46);}).join("")}<text x="160" y="430" text-anchor="middle" font-size="10" font-weight="900" fill="${ink}">Birds remove the more visible moths each generation</text></svg>`; }
function evolveMothSvg(x,y,dark,bark,i,sc){ const body=dark?"#2B2B30":"#E9E4D7", edge=dark?"#111":"#6B6257", visible=(bark==="clean"&&dark)||(bark==="sooty"&&!dark), s=sc||1; return `<g transform="translate(${x} ${y}) rotate(${(i%5-2)*5}) scale(${s})" opacity="${visible?1:.82}" class="${visible?"p2b-pulse":""}"><path d="M0 0 C-54 -28 -88 0 -94 52 C-54 42 -18 34 0 8 C18 34 54 42 94 52 C88 0 54 -28 0 0Z" fill="${body}" stroke="${edge}" stroke-width="3"/><path d="M0 -2 C-10 18 -10 54 0 72 C10 54 10 18 0 -2Z" fill="${dark?"#15151A":"#BEB6A9"}" stroke="${edge}" stroke-width="2"/>${Array.from({length:26},(_,k)=>`<circle cx="${-72+(k*37%144)}" cy="${8+(k*23%45)}" r="${1.5+k%3}" fill="${dark?"#777":"#6D665E"}" opacity=".55"/>`).join("")}</g>`; }
function evolveGraphSvg(st){ const X=i=>46+i/30*244,Y=v=>148-v/100*110, pts=st.hist.map((v,i)=>`${X(i)} ${Y(v)}`).join(" "); return `<svg viewBox="0 0 320 190" role="img" aria-label="Graph of percent dark moths over generations"><rect width="320" height="190" rx="14" fill="#fff"/><path d="M46 38 V148 H292" stroke="${CO}" stroke-width="2"/><text x="170" y="180" text-anchor="middle" font-size="10" font-weight="900" fill="#7A6A66">generations →</text><text x="53" y="28" font-size="10" font-weight="900" fill="#7A6A66">% dark</text>${[0,25,50,75,100].map(v=>`<line x1="46" x2="292" y1="${Y(v)}" y2="${Y(v)}" stroke="#EEE4DC"/><text x="40" y="${Y(v)+4}" text-anchor="end" font-size="10" font-weight="900" fill="#7A6A66">${v}</text>`).join("")}<polyline points="${pts}" fill="none" stroke="#2B2B30" stroke-width="4"/><circle cx="${X(st.hist.length-1)}" cy="${Y(st.dark)}" r="5.5" fill="#111" stroke="#fff" stroke-width="2"/></svg>`; }
function evolveFossilSvg(){ return `<svg viewBox="0 0 410 240" role="img" aria-label="Fossil record layers"><rect width="410" height="240" rx="16" fill="#F8F2E8"/>${[[0,"#D8B98C","oldest: simple shells"],[1,"#C9A176","fish fossils"],[2,"#AE8968","amphibians"],[3,"#8F735C","mammals / birds"]].map((r,i)=>`<rect x="28" y="${168-i*42}" width="354" height="38" rx="8" fill="${r[1]}"/><text x="42" y="${192-i*42}" font-size="13" font-weight="900" fill="#fff">${r[2]}</text>`).join("")}<path d="M316 178 q26 -26 52 0 q-22 30 -52 0" fill="none" stroke="#fff" stroke-width="4"/><path d="M300 126 q34 -24 70 0 m-34 -20 v40" stroke="#fff" stroke-width="4" fill="none"/><path d="M318 76 l20 -18 l20 18 l-8 28 h-24Z" fill="none" stroke="#fff" stroke-width="4"/><text x="205" y="28" text-anchor="middle" font-size="16" font-weight="900" fill="${CO}">Deeper layers are usually older</text></svg>`; }
function evolveBacteriaSvg(st){ const kill=st.strength, surv=Math.round(100-kill*.72); return `<svg viewBox="0 0 320 240" role="img" aria-label="Antibiotic resistance scenario"><rect width="320" height="240" rx="16" fill="#F2FBFF"/><text x="160" y="24" text-anchor="middle" font-size="11" font-weight="900" fill="${CO}">Antibiotic resistance: same selection idea</text>${Array.from({length:21},(_,i)=>{const res=i%8===0,x=34+(i%7)*42,y=54+Math.floor(i/7)*40,dead=!res&&kill>50;return `<g transform="translate(${x} ${y})"><ellipse cx="0" cy="0" rx="16" ry="8" fill="${dead?"#D7D7D7":res?"#3FA06B":"#F28C61"}" stroke="${CO}" stroke-width="1.8" transform="rotate(${i*31%180})"/>${dead?`<path d="M-8 -8 l16 16 M8 -8 l-16 16" stroke="#B33" stroke-width="3"/>`:""}</g>`;}).join("")}<g font-size="10" font-weight="900" fill="${CO}"><text x="24" y="184">Sensitive</text><rect x="92" y="174" width="174" height="14" rx="7" fill="#E9EEF5"/><rect x="92" y="174" width="${Math.max(10,(100-surv)*1.74)}" height="14" rx="7" fill="#F28C61"/><text x="272" y="185">killed</text><text x="24" y="214">Resistant</text><rect x="92" y="204" width="174" height="14" rx="7" fill="#E9EEF5"/><rect x="92" y="204" width="${Math.max(10,surv*1.74)}" height="14" rx="7" fill="#3FA06B"/><text x="272" y="215">multiply</text></g></svg>`; }

SIM_CH.gel = { title:"DNA Evidence Lab", mins:15, story:"Run a gel, identify a DNA fingerprint match, then build an insulin recombinant plasmid.", missions:[
  {ic:"♻️",name:"Copy + cut",tasks:[
    {type:"goal",ic:"♻️",do:"Run <b>PCR to 5 cycles</b>.",look:"PCR buttons",target:"5 cycles",check:p=>p.mode==="dna"&&p.cycles>=5,meter:p=>({v:p.cycles,min:0,max:10,lo:5,hi:10,unit:" cycles",label:"PCR"}),why:"PCR doubles copies each cycle: after 5 cycles there are 2⁵ = 32 copies."},
    {type:"read",ic:"🔢",do:"Read the <b>PCR copy number</b>.",look:"Readout tiles",need:p=>p.cycles>=5,needTxt:"Run PCR to at least 5 cycles.",fields:[["Copies after cycles",p=>p.copies,0," copies"]],why:"Copies double every cycle, so copies = 2ⁿ."},
    {type:"goal",ic:"✂️",do:"Press <b>✂️ Cut</b>, then <b>Load wells</b>.",look:"Action buttons",target:"DNA loaded",check:p=>p.cut&&p.loaded,why:"Restriction enzymes or STR preparation make fragments before loading the wells."}]},
  {ic:"⚡",name:"Run gel",tasks:[
    {type:"goal",ic:"▶",do:"Run the gel past <b>80%</b> and switch on <b>Stain/UV</b>.",look:"Gel tank",target:"run ≥80 + bands visible",check:p=>p.mode==="dna"&&p.run>=80&&p.stain,meter:p=>({v:p.run,min:0,max:100,lo:80,hi:100,unit:"%",label:"Run"}),why:"Staining makes separated DNA bands visible under UV."},
    {type:"pick",ic:"＋",do:"Why does DNA move to the <b>+ anode</b>.",opts:["Its phosphate backbone is negatively charged","It is positively charged","DNA polymerase pulls it","The ladder pushes it"],miss:["","DNA moves towards +, so its overall charge is negative.","DNA polymerase is used in PCR, not gel movement.","The ladder is only a size standard."],why:"Negative DNA is pulled towards the positive electrode."},
    {type:"read",ic:"📏",do:"Select <b>Scene</b>. Read its first two bands.",look:"Lane buttons + gel bands",need:p=>p.lane==="Scene"&&p.stain&&p.run>=80,needTxt:"Run, stain and select the Scene lane.",fields:[["Largest scene band",p=>p.band1,15," bp"],["Second scene band",p=>p.band2,15," bp"]],why:"Use the ladder bands as known sizes, then compare unknown bands."}]},
  {ic:"🎯",name:"Match",tasks:[
    {type:"goal",ic:"🕵️",do:"Select the matching suspect or father lane.",look:"Lane buttons",target:"correct lane selected",check:p=>p.selectedMatch&&p.stain&&p.run>=80,why:"A DNA fingerprint match has the same band pattern. In paternity, every child band comes from mother or father."},
    {type:"pick",ic:"👪",do:"In paternity, what rule identifies the father?",opts:["Every child band must be in the mother or the father","The father must have all the mother's bands","The smallest band is ignored","Only the darkest band matters"],miss:["","The mother already explains some child bands; the father explains the rest.","All visible bands should be considered.","Band position/pattern matters, not just darkness."],why:"A child inherits DNA from both parents."}]},
  {ic:"⭕",name:"Recombinant DNA",tasks:[
    {type:"goal",ic:"⭕",do:"Switch to <b>⭕ Recombinant DNA</b> mode.",look:"Mode buttons",target:"rDNA mode",check:p=>p.mode==="rdna",why:"Genetic engineering uses vectors such as plasmids."},
    {type:"goal",ic:"✂️",do:"Set both enzymes to <b>EcoRI</b>.",look:"Enzyme buttons",target:"same enzyme",check:p=>p.mode==="rdna"&&p.sameEnzyme&&p.plasmidEnz==="EcoRI",why:"The same restriction enzyme makes complementary sticky ends."},
    {type:"goal",ic:"🔗",do:"Step until a <b>recombinant plasmid</b> forms.",look:"Step button + plasmid",target:"recombinant plasmid",check:p=>p.mode==="rdna"&&p.recombinant,why:"DNA ligase joins the insulin gene into the plasmid."},
    {type:"order",ic:"🔢",do:"Order the genetic-engineering steps.",items:["Cut plasmid and insulin gene with the same restriction enzyme","Join sticky ends with DNA ligase","Transform bacteria with the recombinant plasmid","Select and clone transformed bacteria","Grow in a fermenter to produce insulin"],why:"This is the standard recombinant DNA sequence."},
    {type:"goal",ic:"💉",do:"Step until <b>insulin is produced</b>.",look:"Fermenter",target:"insulin produced",check:p=>p.mode==="rdna"&&p.insulin,why:"Transformed bacteria multiply and express the human insulin gene."}]}
]};
SIM_CH.classify = { title:"Name-tag Museum", mins:15, story:"Use visible features to identify HK organisms and build your own dichotomous key.", missions:[
  {ic:"🔑",name:"Use a key",tasks:[
    {type:"goal",ic:"🦀",do:"Select <b>shore crab</b>.",look:"Specimen buttons",target:"crab selected",check:p=>p.mode==="use"&&p.selected==="crab",why:"Crabs are arthropods with jointed legs and a hard carapace."},
    {type:"goal",ic:"✅",do:"Use the key until the result is <b>shore crab</b>.",look:"Yes / No key",target:"key correct",check:p=>p.mode==="use"&&p.keyCorrect&&p.selected==="crab",why:"A dichotomous key follows paired choices to one organism."},
    {type:"pick",ic:"👀",do:"Which feature is best for a key?",need:p=>p.keyCorrect&&p.selected==="crab",needTxt:"Use the key to identify the shore crab first.",opts:["Number of legs", "How cute it looks", "Its given nickname", "Whether it is moving now"],miss:["","Cute is opinion, not a stable observable feature.","Names are what the key finds; they cannot be the clue.","Movement can change from moment to moment."],why:"Good key features are stable and easy to observe."}]},
  {ic:"🛠️",name:"Build a key",tasks:[
    {type:"goal",ic:"🛠️",do:"Switch to <b>🛠️ Build key</b> mode.",look:"Mode buttons",target:"build mode",check:p=>p.mode==="build",why:"A good key separates organisms into smaller groups."},
    {type:"goal",ic:"🔀",do:"Choose at least <b>6 split questions</b>.",look:"Question buttons",target:"6 questions",check:p=>p.mode==="build"&&p.buildCount>=6,meter:p=>({v:p.buildCount,min:0,max:9,lo:6,hi:9,unit:"",label:"Questions"}),why:"Several contrasting features are needed to identify 8 organisms."},
    {type:"goal",ic:"🏁",do:"Make every endpoint have <b>1 organism</b>.",look:"Endpoint boxes",target:"all endpoints single",check:p=>p.mode==="build"&&p.buildSolved,meter:p=>({v:8-p.buildMaxGroup,min:0,max:7,lo:7,hi:7,unit:"",label:"Single endpoint score"}),why:"A finished key ends with one organism at each endpoint."},
    {type:"fill",ic:"✍️",do:"Complete the key rule.",need:p=>p.mode==="build"&&p.buildCount>=6,needTxt:"Choose at least 6 split questions in Build key mode.",text:"A dichotomous key uses pairs of {contrasting|random|Latin} statements based on {observable|hidden|guessed} features.",why:"Contrasting observable features guide the identification."}]},
  {ic:"🏷️",name:"Names + hierarchy",tasks:[
    {type:"goal",ic:"🏷️",do:"Switch to <b>🏷️ Names</b> mode.",look:"Mode buttons",target:"names mode",check:p=>p.mode==="rank",why:"Classification also shows relationships using a hierarchy."},
    {type:"order",ic:"🔢",do:"Order the classification hierarchy.",need:p=>p.mode==="rank",needTxt:"Switch to 🏷️ Names mode.",items:["Domain","Kingdom","Phylum","Class","Order","Family","Genus","Species"],why:"The hierarchy goes from broad groups to one species."},
    {type:"pick",ic:"✍️",do:"Which name follows binomial rules?",need:p=>p.mode==="rank",needTxt:"Switch to 🏷️ Names mode and look at the name cards.",opts:["<i>Sousa chinensis</i>","sousa Chinensis","Sousa chinensis dolphin","<i>Sousa Chinensis</i>"],miss:["","The genus needs a capital letter; species is lower case.","A binomial has two words only.","Species should be lower-case."],why:"Genus capitalised + species lower-case, italic or underlined."},
    {type:"fill",ic:"🌐",do:"Complete the domain/kingdom sentence.",text:"The three domains are {Bacteria|Animalia|Fungi}, {Archaea|Plantae|Mammalia} and {Eukarya|Chordata|Species}. One five-kingdom group is {Animalia|Domain|Genus}.",why:"The notes use three domains and five kingdoms."}]},
  {ic:"🧠",name:"Explain",tasks:[
    {type:"pick",ic:"🐾",do:"What is a species?",opts:["Organisms that can interbreed to produce fertile offspring","All organisms in one kingdom","Any organisms that look similar","A group with the same common name"],miss:["","Kingdom is much broader.","Look-alikes can be different species.","Common names can be vague."],why:"Fertile offspring is the key biological species idea."},
    {type:"pick",ic:"🕷️",do:"Spider vs insect: which clue separates them?",opts:["Spider has 8 legs; insect has 6 legs", "Spider has antennae; insect has none", "Insect has no body segments", "Both are molluscs"],miss:["","This is reversed: insects have antennae.","Insects have head, thorax and abdomen.","Both are arthropods."],why:"Leg number and antennae are visible arthropod clues."}]}
]};
SIM_CH.evolve = { title:"Selection Island", mins:15, story:"Run peppered moth experiments and explain natural selection without the common misconceptions.", missions:[
  {ic:"🌿",name:"Clean bark",tasks:[
    {type:"goal",ic:"🌿",do:"Set bark to <b>🌿 Clean pale</b>.",look:"Bark buttons",target:"clean bark",check:p=>p.clean,why:"Pale moths are better camouflaged on lichen-covered bark."},
    {type:"goal",ic:"▶",do:"Step to <b>generation 3</b>.",look:"Step generation button",target:"generation ≥3",check:p=>p.clean&&p.generation>=3,meter:p=>({v:p.generation,min:0,max:6,lo:3,hi:6,unit:" gen",label:"Generation"}),why:"Selection needs generations because survivors reproduce."},
    {type:"read",ic:"📉",do:"Read the <b>% dark form</b> on clean bark.",look:"Readout + graph",need:p=>p.clean&&p.generation>=3,needTxt:"Use clean bark and step to generation 3.",fields:[["Dark form",p=>p.darkPct,3,"%"]],why:"Dark moths are more visible on pale bark, so their frequency tends to fall."}]},
  {ic:"🏭",name:"Pollution switch",tasks:[
    {type:"goal",ic:"🏭",do:"Change bark to <b>🏭 Sooty dark</b>.",look:"Bark buttons",target:"sooty bark",check:p=>p.sooty,why:"Soot changes which form is better camouflaged."},
    {type:"goal",ic:"📈",do:"Step until dark form is <b>increasing</b>.",look:"Graph + readout",target:"dark increasing",check:p=>p.sooty&&p.darkIncreasing,why:"On dark bark, melanic moths are less visible to birds."},
    {type:"read",ic:"📊",do:"Read the <b>next-generation dark %</b>.",look:"Readout tiles",need:p=>p.sooty&&p.darkIncreasing,needTxt:"Use sooty bark until the next change is positive.",fields:[["Next dark form",p=>p.nextDark,3,"%"]],why:"The model predicts the allele/form frequency after selection and reproduction."}]},
  {ic:"🧬",name:"Explain chain",tasks:[
    {type:"order",ic:"🔢",do:"Order natural selection.",need:p=>p.generation>=1,needTxt:"Step at least 1 generation so the chain lights up.",items:["Variation exists because of mutation","More offspring are produced than survive","There is a struggle for existence","Better adapted individuals survive","Survivors reproduce","Favourable alleles are passed on","Allele frequency changes over generations"],why:"This is the HKDSE natural-selection sequence."},
    {type:"pick",ic:"⚠️",do:"Which sentence avoids the main misconception?",need:p=>p.generation>=1,needTxt:"Run or step the moth model first.",opts:["Populations change; individuals do not change because they need to","Each moth turns dark when the bark gets dark","Acquired camouflage is inherited by offspring","Birds decide to make moths evolve"],miss:["","Individuals do not choose or need-change their genes.","Acquired characters are not inherited in this model.","Birds are a selection pressure, not a designer."],why:"Selection acts on existing heritable variation."},
    {type:"fill",ic:"✍️",do:"Complete the selection sentence.",text:"Birds eat the more {visible|hidden|needed} moths. Survivors {reproduce|change species|learn} and pass on their {alleles|acquired scars|wishes}.",why:"Survival and reproduction make favourable alleles more common."}]},
  {ic:"🦠",name:"Apply evidence",tasks:[
    {type:"pick",ic:"🦠",do:"How does antibiotic resistance increase?",opts:["Resistant mutants survive and multiply","Antibiotics make every bacterium stronger by practice","Sensitive bacteria choose new alleles","Resistance is not inherited"],miss:["","This is a need-based misconception.","Bacteria do not choose mutations.","Resistance alleles can be inherited by daughter cells."],why:"Antibiotics select resistant bacteria already present by mutation."},
    {type:"pick",ic:"🪨",do:"What does the fossil panel show?",opts:["Older fossils are usually in deeper layers","All fossils form in one perfect sequence","Soft-bodied organisms fossilise easily","Fossils alone show DNA sequences"],miss:["","The fossil record is incomplete.","Soft parts decay and rarely fossilise.","Molecular evidence is a different line of evidence."],why:"Rock layers give evidence for changes over time, though the record is incomplete."},
    {type:"fill",ic:"🌋",do:"Complete speciation.",text:"Speciation can happen when populations are {isolated|mixed every day|identical}, face different selection pressures, and can no longer {interbreed|feed|move} to produce fertile offspring.",why:"Isolation plus different selection can form new species."}]}
]};
